reference_solution:
function SumSeq(s: seq<int>): int
{
  if |s| == 0 then 0
  else s[0] + SumSeq(s[1..])
}

method SumArray(a: seq<int>) returns (s: int)
  ensures s == SumSeq(a)
{
  s := 0;
  var i := 0;
  while i < |a|
    invariant 0 <= i <= |a|
    invariant s == SumSeq(a[..i])
  {
    s := s + a[i];
    i := i + 1;
  }
  assert a[..|a|] == a;
}

test_cases:
method Main() {
  var a: seq<int> := [1, 2, 3, 4, 5];
  var s := SumArray(a);
  assert s == 15;
  var b: seq<int> := [];
  var s2 := SumArray(b);
  assert s2 == 0;
}
